// The types of the reference's animation table; the rows' names only. The tables are built at run time from
// the player's paks and installed once (`install`).
use std::sync::{LazyLock, OnceLock};

/// One frame of a root-motion track: seconds; translation since frame 0 in actor space at frame 0
/// (cm: x forward, y right, z up); yaw since frame 0 (degrees, positive = turning right).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct RootKey {
    pub time: f32,
    pub x: f32,
    pub y: f32,
    pub z: f32,
    pub yaw: f32,
}

/// The notify classes the core reads; every other class is `Other`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum NotifyClass {
    TresAnimNotifyEnableChange,
    TresAnimNotifyEnableInput,
    TresAnimNotifyFaceAt,
    TresAnimNotifyLandAnimPose,
    TresAnimNotifyLastAnimPose,
    TresAnimNotifyPlayVoice,
    TresAnimNotifySetWeaponVisible,
    TresAnimNotifyShot,
    TresAnimNotifyStateAttack,
    TresAnimNotifyStateAttackEnableMapHitReflect,
    TresAnimNotifyStateBpEvent,
    TresAnimNotifyStateTraction,
    TresAnimNotifyTiming,
    Other,
}

impl NotifyClass {
    pub const fn game_name(self) -> &'static str {
        match self {
            NotifyClass::TresAnimNotifyEnableChange => "TresAnimNotify_EnableChange",
            NotifyClass::TresAnimNotifyEnableInput => "TresAnimNotify_EnableInput",
            NotifyClass::TresAnimNotifyFaceAt => "TresAnimNotify_FaceAt",
            NotifyClass::TresAnimNotifyLandAnimPose => "TresAnimNotify_LandAnimPose",
            NotifyClass::TresAnimNotifyLastAnimPose => "TresAnimNotify_LastAnimPose",
            NotifyClass::TresAnimNotifyPlayVoice => "TresAnimNotify_PlayVoice",
            NotifyClass::TresAnimNotifySetWeaponVisible => "TresAnimNotify_SetWeaponVisible",
            NotifyClass::TresAnimNotifyShot => "TresAnimNotify_Shot",
            NotifyClass::TresAnimNotifyStateAttack => "TresAnimNotifyState_Attack",
            NotifyClass::TresAnimNotifyStateAttackEnableMapHitReflect => "TresAnimNotifyState_AttackEnableMapHitReflect",
            NotifyClass::TresAnimNotifyStateBpEvent => "TresAnimNotifyState_BpEvent",
            NotifyClass::TresAnimNotifyStateTraction => "TresAnimNotifyState_Traction",
            NotifyClass::TresAnimNotifyTiming => "TresAnimNotify_Timing",
            NotifyClass::Other => "",
        }
    }

    pub fn from_game_name(name: &str) -> NotifyClass {
        match name {
            "TresAnimNotify_EnableChange" => NotifyClass::TresAnimNotifyEnableChange,
            "TresAnimNotify_EnableInput" => NotifyClass::TresAnimNotifyEnableInput,
            "TresAnimNotify_FaceAt" => NotifyClass::TresAnimNotifyFaceAt,
            "TresAnimNotify_LandAnimPose" => NotifyClass::TresAnimNotifyLandAnimPose,
            "TresAnimNotify_LastAnimPose" => NotifyClass::TresAnimNotifyLastAnimPose,
            "TresAnimNotify_PlayVoice" => NotifyClass::TresAnimNotifyPlayVoice,
            "TresAnimNotify_SetWeaponVisible" => NotifyClass::TresAnimNotifySetWeaponVisible,
            "TresAnimNotify_Shot" => NotifyClass::TresAnimNotifyShot,
            "TresAnimNotifyState_Attack" => NotifyClass::TresAnimNotifyStateAttack,
            "TresAnimNotifyState_AttackEnableMapHitReflect" => NotifyClass::TresAnimNotifyStateAttackEnableMapHitReflect,
            "TresAnimNotifyState_BpEvent" => NotifyClass::TresAnimNotifyStateBpEvent,
            "TresAnimNotifyState_Traction" => NotifyClass::TresAnimNotifyStateTraction,
            "TresAnimNotify_Timing" => NotifyClass::TresAnimNotifyTiming,
            _ => NotifyClass::Other,
        }
    }
}

/// One effect of a `TresAnimNotify(State)_AttachEffect`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct EffectAttach {
    pub effect: Option<&'static str>,
    /// `ESQEX_ATTACH_OBJECT_NAME`.
    pub attach_type: &'static str,
    pub socket: &'static str,
    pub group_id: i32,
    pub common: bool,
}

/// The decoded properties of a notify.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum NotifyData {
    None,
    Attack { group: &'static str, row: &'static str, hit_se: Option<&'static str>, interval: Option<f32>, hit_se_asset: Option<&'static str>, override_hit_effect: bool, hit_effect_group: Option<&'static str> },
    Ik { start_interpolation_time: f32, end_interpolation_time: f32, target_alpha: f32 },
    Param { param: Option<i32> },
    Shot { location_index: Option<i32>, attach_fire_effect: bool },
    LandAnimPose { pose: Option<&'static str> },
    LastAnimPose { pose: Option<&'static str> },
    WeaponSe { hit: bool, alias: &'static str, unit: &'static str, socket: Option<&'static str>, follow: bool, volume: f32, pitch: f32, fade_out: f32 },
    Sound { sound: &'static str, attach_point: Option<&'static str>, volume: f32, pitch: f32, fade_in: f32, fade_out: f32, loop_end_sound: Option<&'static str>, loop_end_pitch: f32, follow_owner_visible: bool },
    AutoSe { motion: Option<&'static str>, source: Option<&'static str>, fade_out: f32 },
    Voice { group: Option<&'static str>, asset: Option<&'static str>, random: &'static [(&'static str, i32)], fade_out: f32 },
    Face { slot: u8, anim_type: Option<&'static str>, anim_name: Option<&'static str>, blend_in: f32, looped: bool, same_check: bool, battle_face_end: bool },
    Effect { entries: &'static [EffectAttach] },
}

/// One notify of a sequence: `time` the trigger time, `end` the end trigger of a notify state.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NotifyDef {
    pub class: NotifyClass,
    pub state: bool,
    pub time: f32,
    pub end: f32,
    pub data: NotifyData,
    pub props: &'static [(&'static str, &'static str)],
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SequenceData {
    pub name: &'static str,
    pub length: f32,
    pub frames: u32,
    pub root_motion_enabled: bool,
    pub interpolation_time: f32,
    pub jump_start: f32,
    pub enable_change: f32,
    pub reverse_leg: (f32, f32),
    pub root: &'static [RootKey],
    pub notifies: &'static [NotifyDef],
    /// Clips with a hit window: the Keyblade's sockets per frame, actor space, cm: [ATK_00 xyz, ATK_01 xyz].
    pub sockets: &'static [[f32; 6]],
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BlendSpace2d {
    pub x_min: f32,
    pub x_max: f32,
    pub x_grid: usize,
    pub y_min: f32,
    pub y_max: f32,
    pub y_grid: usize,
    pub y_smoothing: f32,
    pub samples: &'static [(f32, f32, usize)],
    pub grid: &'static [&'static [(usize, f32)]],
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct AnimData {
    pub name: &'static str,
    pub stage1_mode: Option<u8>,
    pub looping: bool,
    pub root_motion_bit: bool,
    pub root_motion: bool,
    pub root_motion_enabled: bool,
    pub blend_in: f32,
    pub length: f32,
    pub sample_lengths_differ: bool,
    pub blend_space: bool,
    pub axis_min: f32,
    pub axis_max: f32,
    pub axis_smoothing: f32,
    pub all_animation: bool,
    pub samples: &'static [(f32, usize)],
    pub space2d: Option<&'static BlendSpace2d>,
}

/// What the player's files give.
#[derive(Clone, Debug, Default)]
pub struct AnimTables {
    pub anims: Vec<AnimData>,
    pub sequences: Vec<SequenceData>,
    pub notify_assets: Vec<&'static str>,
    pub socket_vfx_cure: [f32; 3],
    pub socket_vfx_cure_plus_200: [f32; 3],
}

static TABLES: OnceLock<AnimTables> = OnceLock::new();

/// Installs the tables (once a process).
pub fn install(t: AnimTables) {
    let _ = TABLES.set(t);
}

fn tables() -> &'static AnimTables {
    TABLES.get().expect("kh3_sora: the animation tables are not installed")
}

pub static ANIMS: LazyLock<&'static [AnimData]> = LazyLock::new(|| &tables().anims);
pub static SEQUENCES: LazyLock<&'static [SequenceData]> = LazyLock::new(|| &tables().sequences);
pub static NOTIFY_ASSETS: LazyLock<&'static [&'static str]> = LazyLock::new(|| &tables().notify_assets);
pub static SOCKET_VFX_CURE: LazyLock<[f32; 3]> = LazyLock::new(|| tables().socket_vfx_cure);
pub static SOCKET_VFX_CURE_PLUS_200: LazyLock<[f32; 3]> = LazyLock::new(|| tables().socket_vfx_cure_plus_200);

